insert into public.blog_articles
  (slug, title, excerpt, body_html, tags, status, published_at, seo_meta)
values
  ('start-here', 'Start here: how to use Eurospending', 'A two-minute tour of the site — the map, country pages, the comparison tool, the euro timeline, and the data downloads.', '<p>Eurospending tracks the public finances of the EU and the story of the euro, using only official figures from Eurostat, the European Central Bank (ECB) and the International Monetary Fund (IMF). Here is how the site is laid out.</p><h2>The map and country rankings</h2><p>The home page shows a map of Europe coloured by a chosen metric, and below it a sortable list of every country. Pick a metric to re-rank the list and see who is doing well and who is under strain.</p><h2>Country pages</h2><p>Each country has its own page with a snapshot of headline numbers and charts going back years — debt, deficit, growth, inflation, unemployment and more.</p><h2>Compare</h2><p>The comparison tool puts several countries on one chart for a single metric, so you can see divergence over time.</p><h2>The euro</h2><p>The euro page follows monetary policy and the currency itself: ECB interest rates, the central-bank balance sheet, money supply, exchange rates and inflation.</p><h2>Data and blog</h2><p>Every series can be downloaded from the data page. Throughout the site you will see small information links next to each metric — they bring you to the plain-English explainer for that number, all collected here in the blog.</p>', '{"guide","start-here"}', 'published', now(), '{"og_title":"Start here: how to use Eurospending","og_description":"A two-minute tour of the site — the map, country pages, the comparison tool, the euro timeline, and the data downloads."}'::jsonb),
  ('glossary', 'A plain-English glossary of economic terms', 'Percent of GDP, basis points, real vs nominal, year-on-year, HICP, the Maastricht criteria — the jargon you meet on this site, defined simply.', '<p>Economic data comes wrapped in shorthand. Here are the terms you will meet most often on Eurospending.</p><ul><li><p><strong>% of GDP</strong> — a number measured against the size of the whole economy. Expressing debt or spending this way lets you compare a small country with a large one fairly.</p></li><li><p><strong>Nominal vs real</strong> — nominal figures are in the prices of the day; real figures strip out inflation so you can compare across time. Real growth is the one that tells you whether the economy actually got bigger.</p></li><li><p><strong>Year-on-year (YoY)</strong> — change compared with the same period twelve months earlier. <strong>Quarter-on-quarter (QoQ)</strong> compares with the previous quarter.</p></li><li><p><strong>Basis point</strong> — one hundredth of a percentage point. A rate moving from 2.00% to 2.25% rose 25 basis points.</p></li><li><p><strong>HICP</strong> — the Harmonised Index of Consumer Prices, the EU''s standard measure of inflation, built so member states are measured the same way.</p></li><li><p><strong>Core inflation</strong> — inflation with volatile food and energy stripped out, used to read the underlying trend.</p></li><li><p><strong>The Maastricht criteria</strong> — the EU''s fiscal rulebook: government deficit below 3% of GDP and debt below 60% of GDP.</p></li><li><p><strong>Eurozone vs EU</strong> — the EU is 27 member states; the eurozone is the subset that uses the euro.</p></li></ul>', '{"guide","glossary"}', 'published', now(), '{"og_title":"A plain-English glossary of economic terms","og_description":"Percent of GDP, basis points, real vs nominal, year-on-year, HICP, the Maastricht criteria — the jargon you meet on this site, defined simply."}'::jsonb),
  ('benchmarks-and-thresholds', 'What counts as healthy? Key benchmarks and thresholds', 'The reference lines that turn a raw number into a judgement — the 3% deficit and 60% debt limits, the ECB''s 2% inflation target, and more.', '<p>A number on its own rarely tells you whether a country is doing well. These widely used reference points give the figures meaning.</p><h2>Fiscal: the Maastricht limits</h2><ul><li><p><strong>Deficit under 3% of GDP.</strong> Above this, a government is borrowing heavily relative to the economy.</p></li><li><p><strong>Debt under 60% of GDP.</strong> Many EU states sit well above this; the level at which debt becomes a worry depends on growth and borrowing costs.</p></li></ul><h2>Prices: the ECB target</h2><p>The ECB aims for inflation of <strong>2%</strong> over the medium term. Persistently above 2% erodes the purchasing power of savings and wages; well below can signal a weak economy.</p><h2>Labour</h2><p>There is no official line for unemployment, but rates in the low single digits are generally considered healthy, while double digits indicate slack and hardship.</p><blockquote><p>On the rankings, treat these thresholds as a traffic light: comfortably inside the limit is reassuring, near it is worth watching, beyond it is a strain.</p></blockquote>', '{"guide"}', 'published', now(), '{"og_title":"What counts as healthy? Key benchmarks and thresholds","og_description":"The reference lines that turn a raw number into a judgement — the 3% deficit and 60% debt limits, the ECB''s 2% inflation target, and more."}'::jsonb),
  ('eurozone-vs-eu', 'Eurozone vs EU: what''s the difference?', 'Why some figures cover 27 countries and others only the 20 that share the euro — and why it matters for reading monetary data.', '<p>Two groups of countries appear across this site, and mixing them up leads to confusion.</p><h2>The European Union</h2><p>The EU is a political and economic union of 27 member states. Fiscal data — spending, revenue, deficits, debt — is reported for all of them, plus an EU-wide aggregate.</p><h2>The eurozone</h2><p>The eurozone is the subset of EU members that have adopted the euro as their currency. Monetary policy — interest rates, money supply, the central-bank balance sheet — is set by the ECB for the eurozone as a whole, not for each country.</p><p>So when you see an interest rate or a money-supply figure, it is a single number for the whole currency area. When you see debt or unemployment, it is country by country. Non-euro EU members (and some non-EU European countries) keep their own currencies and their own central banks.</p>', '{"guide"}', 'published', now(), '{"og_title":"Eurozone vs EU: what''s the difference?","og_description":"Why some figures cover 27 countries and others only the 20 that share the euro — and why it matters for reading monetary data."}'::jsonb),
  ('how-we-source-data', 'Where our data comes from and how we check it', 'Only official sources — Eurostat, the ECB and the IMF — pulled by deterministic code, validated before publication, never estimated by us.', '<p>Trust in the numbers is the whole point of this site, so the sourcing rules are strict.</p><h2>Official sources only</h2><ul><li><p><strong>Eurostat</strong> — the EU''s statistical office: public finances, GDP, inflation, unemployment, population and housing.</p></li><li><p><strong>ECB</strong> — interest rates, the Eurosystem balance sheet, money supply, exchange rates and bond yields.</p></li><li><p><strong>IMF</strong> — the World Economic Outlook, used for cross-country forecasts.</p></li></ul><h2>How it is collected</h2><p>Data is fetched by deterministic code that reads the published series directly. We never use AI or estimation to fill in an economic figure — every value traces back to an official release. Numbers are validated before they are stored, and obvious anomalies are flagged rather than published.</p><h2>Revisions</h2><p>Official statistics are revised as more information arrives. When a source updates a past value, the site updates with it, so what you see reflects the latest official position.</p>', '{"guide","methodology"}', 'published', now(), '{"og_title":"Where our data comes from and how we check it","og_description":"Only official sources — Eurostat, the ECB and the IMF — pulled by deterministic code, validated before publication, never estimated by us."}'::jsonb),
  ('currency-debasement-explained', 'Currency debasement, explained', 'Why the euro in your pocket buys less each year, how money-supply growth and inflation connect, and where to watch it in the data.', '<p>"Debasement" once meant mixing cheap metal into gold coins. The modern version is quieter: the supply of money grows faster than the goods and services it can buy, and each unit buys a little less over time.</p><h2>How to see it</h2><ul><li><p><strong>Accumulated inflation.</strong> A single year of 2-3% inflation sounds small, but it compounds. Year after year it adds up to a large fall in what a euro buys — the euro page shows the cumulative figure, not just the annual rate.</p></li><li><p><strong>Money supply.</strong> The broad money measure, M3, tends to grow steadily and at times sharply. When money grows much faster than the real economy, prices tend to follow.</p></li><li><p><strong>The ECB balance sheet.</strong> Large-scale asset purchases expanded the central bank''s balance sheet enormously after 2015 and again in 2020.</p></li></ul><h2>Why it matters</h2><p>Savers and wage earners hold their wealth in euros. If prices rise faster than wages and interest, real purchasing power falls — even when the headline economy looks stable. This is not a forecast; it is arithmetic you can read directly from the inflation, money-supply and exchange-rate series on this site.</p><blockquote><p>The figures here are official ECB and Eurostat data. We present them and let you draw conclusions.</p></blockquote>', '{"analysis"}', 'published', now(), '{"og_title":"Currency debasement, explained","og_description":"Why the euro in your pocket buys less each year, how money-supply growth and inflation connect, and where to watch it in the data."}'::jsonb),
  ('eu-vs-us-china-growth-gap', 'The growth gap: how the EU compares with the US and China', 'Real growth and income per head have pulled apart between the EU, the United States and the fast-growing economies of Asia. What the data shows.', '<p>For two decades the EU has grown more slowly than the United States and far more slowly than China and India. The gap shows up in a few places.</p><ul><li><p><strong>Real GDP growth.</strong> Year after year, US growth has tended to outpace the eurozone''s, and emerging Asia has grown faster still.</p></li><li><p><strong>GDP per capita.</strong> Income per head is the cleanest measure of prosperity. The gap between the average American and the average EU citizen has widened over time.</p></li><li><p><strong>Compounding.</strong> A persistent one- or two-point difference in annual growth becomes an enormous difference in living standards over a generation.</p></li></ul><h2>The caveats</h2><p>Cross-country comparison is harder than it looks: exchange rates, price levels and how output is measured all affect the picture, and the EU scores well on other measures such as inequality and life expectancy. The region-comparison charts on the euro page use IMF data on a consistent basis so the trend is read fairly.</p>', '{"analysis"}', 'published', now(), '{"og_title":"The growth gap: how the EU compares with the US and China","og_description":"Real growth and income per head have pulled apart between the EU, the United States and the fast-growing economies of Asia. What the data shows."}'::jsonb),
  ('tax-spend-and-growth', 'Tax, spend, and growth in the EU', 'Government revenue and spending are large shares of EU economies. The open question is what that buys in growth — and the data lets you look.', '<p>European governments take and spend a large share of national income — generally larger than in the United States. Whether that delivers value is one of the central debates in EU economics, and this site gives you the raw material to weigh it.</p><ul><li><p><strong>Revenue and spending as a share of GDP.</strong> Both run high across most member states, with social protection the single largest spending function.</p></li><li><p><strong>Deficits.</strong> When spending outruns revenue, the gap is borrowed, adding to debt.</p></li><li><p><strong>Growth.</strong> Set these against real GDP growth and GDP per capita and ask the obvious question: is the spending translating into a faster-growing, more prosperous economy?</p></li></ul><p>We take no view for you. The spending, revenue, deficit and growth series are all here, country by country, so you can judge.</p>', '{"analysis"}', 'published', now(), '{"og_title":"Tax, spend, and growth in the EU","og_description":"Government revenue and spending are large shares of EU economies. The open question is what that buys in growth — and the data lets you look."}'::jsonb),
  ('government-spending', 'Government spending (total expenditure)', 'What total general government expenditure as a share of GDP measures, and how to read it.', '<p>Total general government expenditure is everything the state spends — central government, regional and local government, and social-security funds combined. It is shown as a percentage of GDP so countries of different sizes can be compared.</p><h2>Why a share of GDP</h2><p>Expressing spending against the size of the economy answers the real question: how big is the state relative to everything the country produces? In most EU members this sits around or above 45-50% of GDP, high by global standards.</p><h2>What to watch</h2><ul><li><p>Spending that rises faster than revenue produces deficits and, over time, debt.</p></li><li><p>The composition matters as much as the level — see the breakdown by function.</p></li><li><p>Set spending against real growth to ask whether a larger state is buying a faster economy.</p></li></ul><p>Source: Eurostat (general government, sector S13), annual.</p>', '{"explainer","fiscal"}', 'published', now(), '{"og_title":"Government spending (total expenditure)","og_description":"What total general government expenditure as a share of GDP measures, and how to read it."}'::jsonb),
  ('government-spending-by-function', 'Government spending by function: health, education, defence, social protection', 'How the COFOG breakdown splits public spending into what governments actually spend it on.', '<p>Total spending tells you how big the state is; the functional breakdown tells you what it does. Eurostat classifies expenditure using an international standard called COFOG (Classification of the Functions of Government).</p><ul><li><p><strong>Social protection</strong> — pensions, unemployment benefits, family support. Almost always the largest single function in EU budgets.</p></li><li><p><strong>Health</strong> — public healthcare systems and related services.</p></li><li><p><strong>Education</strong> — schools and universities.</p></li><li><p><strong>Defence</strong> — armed forces and military procurement, historically low across much of the EU.</p></li></ul><h2>How to read it</h2><p>Each is shown as a percentage of GDP. Comparing the mix across countries reveals very different priorities — and comparing it over time shows where the long-run pressures, especially ageing-related social protection and health, are building.</p><p>Source: Eurostat COFOG, annual.</p>', '{"explainer","fiscal"}', 'published', now(), '{"og_title":"Government spending by function: health, education, defence, social protection","og_description":"How the COFOG breakdown splits public spending into what governments actually spend it on."}'::jsonb),
  ('government-revenue', 'Government revenue', 'Total general government revenue as a share of GDP — essentially the overall tax-and-contributions take.', '<p>Total general government revenue is everything the state collects: taxes on income and profits, VAT and other taxes on goods, social contributions, and assorted other income. It is shown as a percentage of GDP.</p><h2>What it tells you</h2><p>This is the broadest measure of the tax burden. A high revenue-to-GDP ratio means a large share of national income passes through the state. EU members generally sit at the high end internationally, reflecting extensive welfare and public-service systems.</p><h2>Reading it well</h2><ul><li><p>Compare revenue with expenditure: the gap is the deficit or surplus.</p></li><li><p>A rising ratio can reflect higher tax rates, a larger tax base, or a shrinking private economy — the cause matters.</p></li></ul><p>Source: Eurostat (general government, sector S13), annual.</p>', '{"explainer","fiscal"}', 'published', now(), '{"og_title":"Government revenue","og_description":"Total general government revenue as a share of GDP — essentially the overall tax-and-contributions take."}'::jsonb),
  ('deficit-and-surplus', 'Deficit and surplus (net lending/borrowing)', 'The gap between what a government raises and what it spends in a year, and the 3%-of-GDP Maastricht limit.', '<p>The budget balance — formally net lending (+) or net borrowing (−), item B.9 — is revenue minus spending in a single year. A negative figure is a deficit (the government borrowed to cover the gap); a positive figure is a surplus.</p><h2>The 3% rule</h2><p>The EU''s Maastricht framework asks members to keep their deficit below <strong>3% of GDP</strong>. Breaching it can trigger the Excessive Deficit Procedure. The limit was suspended during the pandemic and has since been reformed, but 3% remains the reference line.</p><h2>Why it matters</h2><p>Deficits are how debt accumulates. A one-off deficit in a downturn is normal and often sensible; persistent deficits in good times push the debt ratio up and leave less room to respond to the next crisis.</p><p>Source: Eurostat, Excessive Deficit Procedure / sector S13, annual.</p>', '{"explainer","fiscal"}', 'published', now(), '{"og_title":"Deficit and surplus (net lending/borrowing)","og_description":"The gap between what a government raises and what it spends in a year, and the 3%-of-GDP Maastricht limit."}'::jsonb),
  ('government-debt', 'Government debt', 'Gross general government debt — the accumulated stock of borrowing — shown both as a share of GDP and in euros, with the 60% limit.', '<p>Government debt is the total stock of what the state owes, built up from years of deficits. We show it two ways: as a percentage of GDP (best for comparing countries) and in absolute euro millions (the headline size).</p><h2>The 60% reference</h2><p>Maastricht set a reference of debt below <strong>60% of GDP</strong>. Many EU members are far above it; a few carry debt above 100% or even 150%.</p><h2>When is debt a problem?</h2><ul><li><p>It depends on the interest rate versus the growth rate: if the economy grows faster than the cost of borrowing, debt can be carried more easily.</p></li><li><p>High debt narrows a government''s room for manoeuvre and exposes it to rising bond yields.</p></li><li><p>The trend matters more than any single year — is the ratio drifting up or coming down?</p></li></ul><p>Source: Eurostat, Maastricht consolidated gross debt, annual.</p>', '{"explainer","debt"}', 'published', now(), '{"og_title":"Government debt","og_description":"Gross general government debt — the accumulated stock of borrowing — shown both as a share of GDP and in euros, with the 60% limit."}'::jsonb),
  ('gdp-and-real-growth', 'GDP and real growth', 'The size of the economy in euros, and how fast it is actually growing once inflation is removed.', '<p>Gross Domestic Product (GDP) is the total value of everything an economy produces. We show two related things.</p><ul><li><p><strong>Nominal GDP</strong> (EUR millions) — the headline size of the economy in today''s prices.</p></li><li><p><strong>Real growth</strong> (% year-on-year, and quarter-on-quarter) — how much the economy grew after stripping out inflation. This is the figure that tells you whether the country is genuinely getting richer.</p></li></ul><h2>Why real, not nominal</h2><p>Nominal GDP can rise simply because prices rose. Real growth removes that effect, so a positive number means more actual output. Two consecutive quarters of negative real growth is the common rule-of-thumb definition of a recession.</p><h2>The bigger picture</h2><p>EU real growth has tended to run slower than the United States for two decades. Comparing the growth series across regions is the heart of the "is the EU falling behind?" question.</p><p>Source: Eurostat national accounts (annual and quarterly).</p>', '{"explainer","growth"}', 'published', now(), '{"og_title":"GDP and real growth","og_description":"The size of the economy in euros, and how fast it is actually growing once inflation is removed."}'::jsonb),
  ('gdp-per-capita', 'GDP per capita', 'Economic output divided by population — the simplest single gauge of average prosperity.', '<p>GDP per capita is the economy''s output divided by its population, in euros per inhabitant. It is the most widely used shorthand for how prosperous a country is on average.</p><h2>What it captures — and misses</h2><ul><li><p>It captures average income generated per person, which tracks living standards reasonably well.</p></li><li><p>It is an average, so it says nothing about how income is distributed.</p></li><li><p>Comparing across currencies and price levels requires care; within the euro area the comparison is cleaner.</p></li></ul><h2>The comparison that matters</h2><p>GDP per capita is where the EU''s growth gap with the United States is most visible: the difference in income per head has widened over the past two decades. It is the number to watch when asking whether Europe is keeping pace.</p><p>Source: Eurostat national accounts, annual, current prices.</p>', '{"explainer","growth"}', 'published', now(), '{"og_title":"GDP per capita","og_description":"Economic output divided by population — the simplest single gauge of average prosperity."}'::jsonb),
  ('unemployment', 'Unemployment rate', 'The share of people who want work and cannot find it — the headline gauge of labour-market health.', '<p>The unemployment rate is the number of people without a job who are actively looking, as a percentage of the labour force (those working or looking, aged 15-74). We show both the annual average and the more timely monthly series.</p><h2>How to read it</h2><ul><li><p>Low single digits generally indicate a healthy labour market; double digits signal serious slack and hardship.</p></li><li><p>It is a lagging indicator — it tends to keep rising for a while after a downturn ends.</p></li><li><p>It excludes people who have given up looking, so it can understate weakness.</p></li></ul><h2>Wide divergence</h2><p>Unemployment varies enormously across the EU, and youth unemployment in particular has run very high in parts of southern Europe. The monthly series is the best early read on the labour market between annual updates.</p><p>Source: Eurostat labour force survey (annual and monthly).</p>', '{"explainer","labour"}', 'published', now(), '{"og_title":"Unemployment rate","og_description":"The share of people who want work and cannot find it — the headline gauge of labour-market health."}'::jsonb),
  ('population', 'Population', 'Total population on 1 January — the denominator behind per-capita figures and a slow-moving driver of everything else.', '<p>Population is the total number of people resident in a country on 1 January each year. It looks like a simple count, but it underpins a great deal.</p><h2>Why it matters</h2><ul><li><p>It is the denominator for per-capita measures — GDP per capita, money supply per person, debt per head.</p></li><li><p>An ageing, slow-growing population raises pension and health spending while shrinking the working-age base that funds it.</p></li><li><p>Most EU population change now comes from migration rather than natural increase (births minus deaths), which has turned negative in many member states.</p></li></ul><p>Source: Eurostat demographics, population on 1 January, annual.</p>', '{"explainer","demographics"}', 'published', now(), '{"og_title":"Population","og_description":"Total population on 1 January — the denominator behind per-capita figures and a slow-moving driver of everything else."}'::jsonb),
  ('inflation-hicp', 'Inflation (HICP)', 'The Harmonised Index of Consumer Prices — the EU''s standard measure of how fast the cost of living is rising.', '<p>The Harmonised Index of Consumer Prices (HICP) measures the average change in the prices households pay for a representative basket of goods and services. It is "harmonised" so every EU country is measured the same way and the figures are comparable.</p><h2>Annual, monthly, headline</h2><ul><li><p>The <strong>annual</strong> rate compares prices with twelve months earlier — the standard "inflation is X%" figure.</p></li><li><p>The <strong>monthly</strong> series gives a more timely read between annual updates.</p></li><li><p>The <strong>eurozone headline</strong> rate is the single figure the ECB targets.</p></li></ul><h2>Why it matters</h2><p>The ECB aims for 2% over the medium term. Inflation above that erodes the purchasing power of wages and savings; the effect compounds, so several years of moderate inflation add up to a large fall in what a euro buys. See the accumulated-inflation view on the euro page.</p><p>Source: Eurostat and ECB (HICP).</p>', '{"explainer","inflation"}', 'published', now(), '{"og_title":"Inflation (HICP)","og_description":"The Harmonised Index of Consumer Prices — the EU''s standard measure of how fast the cost of living is rising."}'::jsonb),
  ('core-inflation', 'Core inflation', 'Inflation with volatile food and energy stripped out, used to read the underlying price trend.', '<p>Core inflation is the HICP with the most volatile components — energy, food, alcohol and tobacco — removed. The aim is to see the underlying trend without the noise of swinging oil and food prices.</p><h2>Why look at core</h2><ul><li><p>Headline inflation can spike or drop sharply on energy prices alone, which can mislead about the underlying picture.</p></li><li><p>Core moves more slowly and is a better guide to whether inflation is becoming embedded in wages and services.</p></li><li><p>Central banks watch core closely when deciding whether a burst of inflation is temporary or persistent.</p></li></ul><p>When headline inflation falls but core stays high, it usually means the original shock has faded but price pressure has spread through the wider economy.</p><p>Source: Eurostat and ECB (HICP excluding energy, food, alcohol and tobacco).</p>', '{"explainer","inflation"}', 'published', now(), '{"og_title":"Core inflation","og_description":"Inflation with volatile food and energy stripped out, used to read the underlying price trend."}'::jsonb),
  ('ecb-policy-rates', 'ECB policy interest rates', 'The three rates the European Central Bank sets to steer the cost of money across the eurozone.', '<p>The ECB sets the price of money for the whole eurozone through three official rates. Together they form a corridor that steers the rates banks charge each other, and ultimately what households and firms pay.</p><ul><li><p><strong>Main refinancing rate</strong> — the headline policy rate, the cost of the ECB''s regular lending to banks.</p></li><li><p><strong>Deposit facility rate</strong> — what banks earn for parking spare cash at the ECB overnight. Since the era of abundant reserves this has become the rate that matters most for market rates.</p></li><li><p><strong>Marginal lending rate</strong> — the ceiling: the cost of borrowing from the ECB overnight.</p></li></ul><h2>Why they move</h2><p>The ECB raises rates to cool inflation and cuts them to support a weak economy. Rates were negative or near zero for much of the 2010s, then rose sharply from 2022 to fight the inflation surge. These are eurozone-wide — one setting for twenty countries.</p><p>Source: ECB.</p>', '{"explainer","monetary"}', 'published', now(), '{"og_title":"ECB policy interest rates","og_description":"The three rates the European Central Bank sets to steer the cost of money across the eurozone."}'::jsonb),
  ('ecb-balance-sheet', 'The Eurosystem balance sheet', 'The total assets held by the ECB and national central banks — a direct read on how much money the central bank has created.', '<p>The Eurosystem balance sheet is the combined total assets of the ECB and the national central banks of the eurozone. When the central bank buys bonds or lends to banks, it creates new central-bank money and its balance sheet grows.</p><h2>Why it ballooned</h2><p>Through quantitative easing (large-scale asset purchases) from 2015, and again massively during the pandemic from 2020, the balance sheet expanded to a size unimaginable in the euro''s early years. From 2022 the ECB began shrinking it again ("quantitative tightening").</p><h2>Why it matters</h2><ul><li><p>It is the clearest single gauge of how much money the central bank has injected.</p></li><li><p>Rapid expansion is closely tied to the money-supply growth and asset-price moves discussed in our debasement explainer.</p></li><li><p>Unwinding it removes liquidity and can push up bond yields.</p></li></ul><p>Source: ECB, weekly consolidated financial statement.</p>', '{"explainer","monetary"}', 'published', now(), '{"og_title":"The Eurosystem balance sheet","og_description":"The total assets held by the ECB and national central banks — a direct read on how much money the central bank has created."}'::jsonb),
  ('money-supply', 'Money supply (M1, M2, M3)', 'How much money exists in the eurozone, from cash and current accounts up to the broad measure the ECB tracks.', '<p>"Money supply" is the total stock of money in the economy. It comes in nested measures, from narrow to broad.</p><ul><li><p><strong>M1</strong> — the most liquid money: cash in circulation plus overnight deposits (current accounts).</p></li><li><p><strong>M2</strong> — M1 plus deposits with a short maturity or notice period.</p></li><li><p><strong>M3</strong> — the broad measure the ECB watches: M2 plus repos, money-market fund shares and short-term debt securities.</p></li></ul><h2>Why it matters</h2><p>Over the long run, when the money supply grows much faster than the real economy, prices tend to rise — money loses value. M3 growth is therefore a key signal behind inflation and currency debasement. Dividing money supply by population gives money per person, a useful way to see the trend free of compounding totals.</p><p>Source: ECB monetary aggregates (eurozone), monthly.</p>', '{"explainer","monetary"}', 'published', now(), '{"og_title":"Money supply (M1, M2, M3)","og_description":"How much money exists in the eurozone, from cash and current accounts up to the broad measure the ECB tracks."}'::jsonb),
  ('exchange-rates', 'Exchange rates (EUR/USD, EUR/GBP)', 'What one euro buys in dollars and pounds — the external value of the currency.', '<p>An exchange rate is the price of one currency in terms of another. EUR/USD is how many US dollars one euro buys; EUR/GBP is how many pounds. These are the ECB''s daily reference rates.</p><h2>What moves them</h2><ul><li><p>Interest-rate differences — money tends to flow toward higher-yielding currencies.</p></li><li><p>Relative growth and inflation prospects.</p></li><li><p>Risk sentiment — in turmoil the dollar often strengthens as a safe haven.</p></li></ul><h2>Internal vs external value</h2><p>Inflation measures the euro''s <em>internal</em> value (what it buys at home); the exchange rate is its <em>external</em> value (what it buys abroad). A currency can hold up against peers while still losing purchasing power at home if those peers are inflating too. Both views matter when judging the health of the euro.</p><p>Source: ECB reference exchange rates, daily.</p>', '{"explainer","monetary"}', 'published', now(), '{"og_title":"Exchange rates (EUR/USD, EUR/GBP)","og_description":"What one euro buys in dollars and pounds — the external value of the currency."}'::jsonb),
  ('bond-yields', 'Government bond yields (10-year)', 'The interest rate governments pay to borrow for ten years — and what the spread between countries reveals.', '<p>A government bond yield is the annual return an investor earns for lending to a government for a given term. The 10-year yield is the standard benchmark for long-term borrowing costs.</p><ul><li><p><strong>German Bund (10Y)</strong> — the eurozone''s safe-asset benchmark; other countries are judged against it.</p></li><li><p><strong>Sovereign 10Y yields</strong> — the equivalent for individual countries, in euros.</p></li><li><p><strong>Local-currency yields</strong> — for EU members outside the euro, in their own currency.</p></li></ul><h2>Spreads tell the story</h2><p>The gap ("spread") between a country''s yield and the Bund reflects the extra risk investors demand. Widening spreads — as in the 2010-2012 sovereign debt crisis — signal stress; narrow spreads signal confidence. Yields also set the cost of carrying government debt, which is why they matter so much for highly indebted states.</p><p>Source: ECB / national benchmarks, daily.</p>', '{"explainer","monetary"}', 'published', now(), '{"og_title":"Government bond yields (10-year)","og_description":"The interest rate governments pay to borrow for ten years — and what the spread between countries reveals."}'::jsonb),
  ('housing-cost-burden', 'Housing cost burden', 'The share of people spending more than 40% of their income on housing — a direct measure of affordability stress.', '<p>The housing cost overburden rate is the share of the population living in households that spend more than <strong>40% of disposable income</strong> on housing — rent or mortgage, plus utilities and upkeep. It is a direct gauge of how many people are squeezed by housing costs.</p><h2>Why it matters</h2><ul><li><p>Housing is the largest cost in most household budgets, so overburden is a strong signal of financial stress.</p></li><li><p>It captures something headline inflation can miss — a cost-of-living problem concentrated in shelter.</p></li><li><p>Rates vary widely across the EU and tend to be worst for renters and lower-income households.</p></li></ul><p>Watching this alongside inflation gives a fuller picture of real living standards than prices alone.</p><p>Source: Eurostat, EU Statistics on Income and Living Conditions (ilc_lvho07a), annual.</p>', '{"explainer","housing"}', 'published', now(), '{"og_title":"Housing cost burden","og_description":"The share of people spending more than 40% of their income on housing — a direct measure of affordability stress."}'::jsonb),
  ('migration-and-population-change', 'Net migration and population change', 'Why most EU population change now comes from migration rather than births, and how the crude rates are measured.', '<p>Eurostat breaks the year-on-year change in a country''s population into two crude rates, each expressed per 1,000 people so countries of different sizes compare fairly.</p><ul><li><p><strong>Net migration rate</strong> — arrivals minus departures (plus a small statistical adjustment), per 1,000 population. A positive figure means more people moved in than out.</p></li><li><p><strong>Population change rate</strong> — the total change in population per 1,000, combining net migration with natural change (births minus deaths).</p></li></ul><h2>Why it matters</h2><p>Across most of the EU, natural change has turned negative — more deaths than births — so net migration is now the main thing keeping populations from shrinking. Population is the denominator behind per-capita prosperity and the working-age base that funds pensions and healthcare, which makes these rates a quiet but powerful driver of the public finances tracked elsewhere on this site.</p><blockquote><p>These are demographic accounting rates, not a judgement. We show the figure; the interpretation is yours.</p></blockquote><p>Source: Eurostat demographics (demo_gind), annual.</p>', '{"explainer","demographics"}', 'published', now(), '{"og_title":"Net migration and population change","og_description":"Why most EU population change now comes from migration rather than births, and how the crude rates are measured."}'::jsonb),
  ('imf-forecasts', 'IMF forecasts (World Economic Outlook)', 'Forward-looking projections for growth, inflation, deficits and debt, on a consistent cross-country basis.', '<p>Most of this site reports what has already happened. The IMF''s World Economic Outlook (WEO) looks ahead, with projections produced on a consistent basis for almost every country in the world — which makes it ideal for fair cross-country comparison.</p><ul><li><p><strong>GDP growth forecast</strong> — projected real growth.</p></li><li><p><strong>Inflation forecast</strong> — projected consumer-price inflation.</p></li><li><p><strong>Net lending/borrowing forecast</strong> — the projected budget balance, % of GDP.</p></li><li><p><strong>Gross debt forecast</strong> — projected government debt, % of GDP.</p></li></ul><h2>How to treat a forecast</h2><p>A projection is not a fact. The IMF revises the WEO twice a year as conditions change, and turning points are often missed. Treat these as the best consistent baseline, not a promise — and the consistent methodology is exactly why we use WEO for comparing the eurozone with the US and Asia.</p><p>Source: IMF World Economic Outlook, annual (historical and projected).</p>', '{"explainer","forecasts"}', 'published', now(), '{"og_title":"IMF forecasts (World Economic Outlook)","og_description":"Forward-looking projections for growth, inflation, deficits and debt, on a consistent cross-country basis."}'::jsonb)
